# Purpose: Redraw exactly three dissertation figures from reviewed aggregates.
# Input: Three allowlisted CSVs in outputs/selected_results/reported_aggregates/.
# Output: Three PNGs in figures/. Run from the repository root.
# Verification: STATIC-ONLY; R was unavailable during Phase 2.
# The delivered PNGs were generated by the accompanying Python/Matplotlib code.
# Presentation only, not a research pipeline stage: no model fitting, prediction,
# feature construction or sourcing of scripts 01-14 occurs here.
# Rscript --vanilla R/15_make_portfolio_figures.R

input_dir <- "outputs/selected_results/reported_aggregates"
output_dir <- "figures"
expected_md5 <- c(
  "figure_4_1_gap_reduction_reported.csv" = "d0a5dcf71bd375035be09d079f9d1553",
  "figure_4_2_disagreement_by_uncertainty_reported.csv" = "0e93c881de3825811ac19933ab9eaae4",
  "figure_4_3_disagreement_logloss_reported.csv" = "317235da29055d5694dbe3f45a31c57d"
)

read_reviewed <- function(name) {
  path <- file.path(input_dir, name)
  if (!file.exists(path)) stop("Missing reviewed aggregate: ", path)
  if (!identical(unname(tools::md5sum(path)), unname(expected_md5[name]))) {
    stop("Reviewed source bytes changed: ", name)
  }
  read.csv(path, stringsAsFactors = FALSE, check.names = FALSE)
}

gap <- read_reviewed("figure_4_1_gap_reduction_reported.csv")
rate <- read_reviewed("figure_4_2_disagreement_by_uncertainty_reported.csv")
loss <- read_reviewed("figure_4_3_disagreement_logloss_reported.csv")
stopifnot(
  nrow(gap) == 8L, nrow(rate) == 4L, nrow(loss) == 4L,
  identical(rate$ttt_uncertainty_quartile, paste0("Q", 1:4)),
  identical(loss$ttt_uncertainty_quartile, paste0("Q", 1:4)),
  sum(loss$disagreement_match_count) == 1496L,
  all(is.finite(gap$gap_closed_percent)),
  all(is.finite(rate$test_disagreement_rate_percent)),
  all(gap$gap_closed_percent >= 0 & gap$gap_closed_percent <= 100),
  all(rate$test_disagreement_rate_percent >= 0 &
        rate$test_disagreement_rate_percent <= 100)
)
loss_columns <- c("bookmaker_logloss", "ttt_logloss",
                  "primary_logistic_logloss", "primary_nn_logloss")
stopifnot(all(is.finite(as.matrix(loss[loss_columns]))),
          all(as.matrix(loss[loss_columns]) >= 0))
dir.create(output_dir, recursive = TRUE, showWarnings = FALSE)

ink <- "#1E293B"
muted <- "#526174"
grid <- "#E2E8F0"
logistic_col <- "#0072B2"
nn_col <- "#009E73"
ttt_col <- "#D55E00"
book_col <- "#263238"
extension_col <- "#CBD5E1"

with_png <- function(name, width, height, draw) {
  path <- file.path(output_dir, name)
  if (capabilities("cairo")) {
    grDevices::png(path, width = width, height = height, res = 200, type = "cairo")
  } else {
    grDevices::png(path, width = width, height = height, res = 200)
  }
  on.exit(grDevices::dev.off(), add = TRUE)
  graphics::par(family = "sans", fg = ink, col.axis = muted,
                col.lab = ink, xaxs = "i", yaxs = "i", las = 1)
  draw()
  message("Created ", path, " from reviewed reported aggregates")
}

source_note <- function(note, source) {
  graphics::mtext(note, side = 1, outer = TRUE, line = 2.1,
                  adj = 0.02, col = muted, cex = 0.77)
  graphics::mtext(paste0("Redraw of dissertation-reported aggregates. ",
                        source, ". Models not rerun."),
                  side = 1, outer = TRUE, line = 3.4,
                  adj = 0.02, col = muted, cex = 0.72)
}

with_png("test_gap_reduction.png", 2440, 1680, function() {
  graphics::par(mfrow = c(2, 1), oma = c(6, 0, 4, 0),
                mar = c(3.7, 17, 2.6, 3.5))
  families <- c("Logistic regression", "Neural network")
  labels <- list(
    c("Full + short-term", "Full + short-term\n+ head-to-head",
      "Full + short-term\n+ common opponent",
      "Full + short-term + head-to-head\n+ common opponent"),
    c("Short-term", "Short-term + head-to-head",
      "Short-term + common opponent",
      "Short-term + head-to-head\n+ common opponent")
  )
  for (i in 1:2) {
    d <- gap[gap$model_family == families[i], , drop = FALSE]
    stopifnot(nrow(d) == 4L, sum(d$model_role == "primary") == 1L)
    y <- 4:1
    primary_col <- c(logistic_col, nn_col)[i]
    colors <- ifelse(d$model_role == "primary", primary_col, extension_col)
    graphics::plot(NA_real_, NA_real_, xlim = c(0, 70), ylim = c(0.5, 4.5),
                   xlab = "", ylab = "", axes = FALSE)
    graphics::abline(v = seq(0, 70, 10), col = grid, lwd = 1)
    graphics::rect(0, y - 0.29, d$gap_closed_percent, y + 0.29,
                   col = colors, border = NA)
    graphics::axis(1, at = seq(0, 70, 10),
                   labels = paste0(seq(0, 70, 10), "%"), cex.axis = 0.9)
    graphics::axis(2, at = y, labels = labels[[i]], tick = FALSE, cex.axis = 0.85)
    graphics::title(families[i], adj = 0, line = 0.6, cex.main = 1.05)
    graphics::text(d$gap_closed_percent + 0.8, y,
                   labels = sprintf("%.1f%%", d$gap_closed_percent),
                   adj = 0, cex = 0.87,
                   font = ifelse(d$model_role == "primary", 2, 1),
                   col = ifelse(d$model_role == "primary", primary_col, ink))
  }
  graphics::mtext("TTT-bookmaker log-loss gap closed (%)", side = 1, line = 2.4)
  graphics::mtext("Closing the test log-loss gap", side = 3, outer = TRUE,
                  line = 2.1, adj = 0.02, cex = 1.35, font = 2)
  graphics::mtext("Overall test set, 2023-2025: 7,725 matches",
                  side = 3, outer = TRUE, line = 0.7, adj = 0.02,
                  cex = 0.85, col = muted)
  source_note("Colored bars: validation-selected primaries. Gray bars: predefined extensions.",
              "Figure 4.1, PDF p.57")
})

with_png("disagreement_by_uncertainty.png", 2120, 1260, function() {
  graphics::par(oma = c(5, 0, 4, 0), mar = c(5, 5.6, 1, 2))
  graphics::plot(NA_real_, NA_real_, xlim = c(0.7, 4.3), ylim = c(0, 30),
                 xlab = "", ylab = "TTT-bookmaker disagreement rate", axes = FALSE)
  graphics::abline(h = seq(0, 30, 5), col = grid, lwd = 1)
  graphics::lines(1:4, rate$test_disagreement_rate_percent, col = ttt_col, lwd = 2.5)
  graphics::points(1:4, rate$test_disagreement_rate_percent,
                   col = ttt_col, pch = 16, cex = 1.1)
  graphics::axis(1, at = 1:4, labels = c("Q1\nLowest", "Q2", "Q3", "Q4\nHighest"))
  graphics::axis(2, at = seq(0, 30, 5), labels = paste0(seq(0, 30, 5), "%"))
  graphics::mtext("TTT skill uncertainty group", side = 1, line = 3.4)
  graphics::text(1:4, rate$test_disagreement_rate_percent + 1.3,
                 labels = sprintf("%.2f%%", rate$test_disagreement_rate_percent),
                 col = ttt_col, font = 2, cex = 0.95)
  graphics::mtext("Disagreement rises with TTT uncertainty",
                  side = 3, outer = TRUE, line = 2.1,
                  adj = 0.02, cex = 1.35, font = 2)
  graphics::mtext("All test matches, 2023-2025: 7,725 matches",
                  side = 3, outer = TRUE, line = 0.7, adj = 0.02,
                  cex = 0.85, col = muted)
  source_note("Training quartile cutoffs held fixed. Each rate uses all test matches in that group.",
              "Figure 4.2, PDF p.60")
})

with_png("disagreement_logloss_by_uncertainty.png", 2120, 1380, function() {
  graphics::par(oma = c(5, 0, 5, 0), mar = c(5, 5.3, 2, 2))
  colors <- c(book_col, ttt_col, logistic_col, nn_col)
  symbols <- c(16, 17, 15, 18)
  styles <- c(1, 2, 4, 3)
  graphics::plot(NA_real_, NA_real_, xlim = c(0.75, 4.52), ylim = c(0.58, 1.045),
                 xlab = "", ylab = "Log loss", axes = FALSE)
  graphics::abline(h = seq(0.6, 1.0, 0.1), col = grid, lwd = 1)
  for (i in seq_along(loss_columns)) {
    values <- loss[[loss_columns[i]]]
    graphics::lines(1:4, values, col = colors[i], lty = styles[i], lwd = 2.4)
    graphics::points(1:4, values, col = colors[i], pch = symbols[i], cex = 0.95)
    graphics::text(4.09, values[4], sprintf("%.4f", values[4]),
                   adj = 0, col = colors[i], cex = 0.9, font = 2)
  }
  graphics::axis(1, at = 1:4,
                 labels = paste0(loss$ttt_uncertainty_quartile, "\nn = ",
                                 loss$disagreement_match_count))
  graphics::axis(2, at = seq(0.6, 1.0, 0.1))
  graphics::mtext("TTT uncertainty group (Q1 lowest, Q4 highest)",
                  side = 1, line = 3.4)
  graphics::legend("topleft", inset = c(0, -0.15), xpd = NA, bty = "n", ncol = 2,
                   legend = c("Bookmaker benchmark", "TTT baseline",
                              "Primary logistic", "Primary neural network"),
                   col = colors, pch = symbols, lty = styles, lwd = 2,
                   cex = 0.88, seg.len = 2.5)
  graphics::mtext("Forecast error within disagreement matches",
                  side = 3, outer = TRUE, line = 3.3,
                  adj = 0.02, cex = 1.35, font = 2)
  graphics::mtext("Test disagreement subset, 2023-2025: 1,496 matches. Lower log loss is better.",
                  side = 3, outer = TRUE, line = 1.9,
                  adj = 0.02, cex = 0.85, col = muted)
  source_note("Training quartile cutoffs held fixed. Counts refer only to test disagreement matches.",
              "Figure 4.3, PDF pp.61-62")
})
